/bin/bash -lc "python3 - <<'PY'
import csv,json
from pathlib import Path
rows=list(csv.DictReader(Path('deaths.csv').read_text(encoding='utf-8',errors='replace').splitlines()))
r=json.load(open('covid-deaths.check.json'))
bad={a['value'] for a in r['join']['unmatched']}
lines=['COVID-19 deaths by country','Source: user-provided deaths.csv. Original source and data date unspecified.','Circle area represents death counts, not deaths per capita. Equal Earth equal-area projection.','226 of 240 rows match boundaries. Small circles and overlapping circles limit comparisons.','Automatic fixes: none. Original CSV unchanged.','','Unmatched rows (no closest-name suggestions supplied by the join tool):']
for a in rows:
 if a['code'] in bad: lines.append(f\"- {a['country']} [{a['code']}]: {a['deaths']} deaths\")
lines+=['','Matched rows with zero deaths have no proportional circle:']
for a in rows:
 if a['code'] not in bad and float(a['deaths'])<=0: lines.append(f\"- {a['country']} [{a['code']}]: {a['deaths']}\")
Path('covid-deaths-notes.txt').write_text('\\n'.join(lines)+'\\n')
print('\\n'.join(lines))
PY"
